class Bank:
    def __init__(self, balance):
        self.balance = balance
        self.n = len(balance)
    def valid(self, acc):
        return 1 <= acc <= self.n
    def transfer(self, a1, a2, money):
        if not self.valid(a1) or not self.valid(a2) or self.balance[a1-1] < money:
            return False
        self.balance[a1-1] -= money
        self.balance[a2-1] += money
        return True
    def deposit(self, acc, money):
        if not self.valid(acc): return False
        self.balance[acc-1] += money
        return True
    def withdraw(self, acc, money):
        if not self.valid(acc) or self.balance[acc-1] < money: return False
        self.balance[acc-1] -= money
        return True

class Solution:
    def countMaxOrSubsets(self, nums) -> int:
        max_or = 0
        for x in nums:
            max_or |= x
        self.count = 0
        def dfs(i, cur):
            if i == len(nums):
                if cur == max_or:
                    self.count += 1
                return
            dfs(i+1, cur | nums[i])
            dfs(i+1, cur)
        dfs(0, 0)
        return self.count

class Solution:
    def secondMinimum(self, n, edges, time, change):
        from collections import deque, defaultdict
        g = defaultdict(list)
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)
        dist = [[float('inf')]*2 for _ in range(n+1)]
        dist[1][0] = 0
        q = deque([(0, 1)])
        while q:
            d, u = q.popleft()
            for v in g[u]:
                nd = d + 1
                if nd < dist[v][0]:
                    dist[v][0] = nd
                    q.append((nd, v))
                elif dist[v][0] < nd < dist[v][1]:
                    dist[v][1] = nd
                    q.append((nd, v))
        steps = dist[n][1]
        ans = 0
        for _ in range(steps):
            if (ans // change) % 2 == 1:
                ans = (ans // change + 1) * change
            ans += time
        return ans

