class Solution:
    def countValidWords(self, sentence: str) -> int:
        def valid(t):
            hyphen = 0
            for i, c in enumerate(t):
                if c.isdigit(): return False
                if c == '-':
                    hyphen += 1
                    if hyphen > 1: return False
                    if i == 0 or i == len(t)-1: return False
