    def countHighestScoreNodes(self, parents):
        from collections import defaultdict
        n = len(parents)
        children = defaultdict(list)
        for i in range(1, n):
            children[parents[i]].append(i)
        size = [0] * n
        def dfs(u):
            size[u] = 1
            for v in children[u]:
                dfs(v)
                size[u] += size[v]
        dfs(0)
        max_score = 0
        count = 0
        for i in range(n):
            score = 1
            remain = n - 1
            for c in children[i]:
