class Solution:
    def minimumTime(self, n, relations, time):
        from collections import deque, defaultdict
        g = defaultdict(list)
        indeg = [0] * (n+1)
        for u, v in relations:
            g[u].append(v)
            indeg[v] += 1
        dist = [0] * (n+1)
        q = deque()
        for i in range(1, n+1):
            if indeg[i] == 0:
                q.append(i)
                dist[i] = time[i-1]
        while q:
            u = q.popleft()
            for v in g[u]:
                dist[v] = max(dist[v], dist[u] + time[v-1])
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        return max(dist)

