        dp = [float('inf')] * (n+1)
        dp[0] = 0
        for i in range(1, n+1):
            length = 0
            for j in range(i, 0, -1):
                length += len(words[j-1])
                if length > k: break
                if j < i: length += 1
                if length > k: break
                if i == n:
                    dp[i] = min(dp[i], dp[j-1])
