class Solution:
    def maximalPathQuality(self, values, edges, maxTime):
        from collections import defaultdict
        g = defaultdict(list)
        for u, v, t in edges:
            g[u].append((v, t))
            g[v].append((u, t))
        self.ans = 0
        visited = [0]*len(values)
        visited[0] = 1
        def dfs(u, time_left, quality):
            if u == 0:
                self.ans = max(self.ans, quality)
            for v, t in g[u]:
                if time_left >= t:
                    bonus = values[v] if visited[v] == 0 else 0
                    visited[v] += 1
                    dfs(v, time_left - t, quality + bonus)
                    visited[v] -= 1
        dfs(0, maxTime, values[0])
        return self.ans

