class Solution:
    def reverseEvenLengthGroups(self, head):
        curr = head
        group = 1
        while curr:
            nodes = []
            temp = curr
            for _ in range(group):
                if not temp: break
                nodes.append(temp)
                temp = temp.next
            actual_len = len(nodes)
            if actual_len % 2 == 0:
                vals = [n.val for n in nodes][::-1]
