class Solution:
    def kMirror(self, k: int, n: int) -> int:
        def is_k_palindrome(num, k):
            digits = []
            while num:
                digits.append(num % k)
                num //= k
            return digits == digits[::-1]
        def gen_palindromes():
            for length in range(1, 20):
                half = (length+1)//2
                start = 10**(half-1) if half > 0 else 0
                end = 10**half
                for i in range(start, end):
                    s = str(i)
                    if length % 2 == 0:
                        pal = s + s[::-1]
                    else:
                        pal = s + s[-2::-1]
                    yield int(pal)
        total = 0
        count = 0
        for p in gen_palindromes():
            if is_k_palindrome(p, k):
                total += p
                count += 1
                if count == n:
                    return total
        return total

