class Solution:
    def findAllPeople(self, n, meetings, firstPerson):
        from collections import defaultdict
        meetings.sort(key=lambda x: x[2])
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            pa, pb = find(a), find(b)
            if pa != pb: parent[pa] = pb
        parent[firstPerson] = 0
        i = 0
        while i < len(meetings):
            j = i
            while j < len(meetings) and meetings[j][2] == meetings[i][2]:
                j += 1
            people = set()
            for k in range(i, j):
                a, b, _ = meetings[k]
                union(a, b)
                people.add(a)
                people.add(b)
            for p in people:
                if find(p) != find(0):
                    parent[p] = p
            i = j
        return [i for i in range(n) if find(i) == find(0)]

class Solution:
    def minimumCost(self, n, highways, discounts):
        import heapq
        from collections import defaultdict
        g = defaultdict(list)
        for u, v, w in highways:
            g[u].append((v, w))
            g[v].append((u, w))
        dist = [[float('inf')]*(discounts+1) for _ in range(n)]
        dist[0][0] = 0
        pq = [(0, 0, 0)]
        while pq:
            d, u, used = heapq.heappop(pq)
            if u == n-1: return d
            if d > dist[u][used]: continue
            for v, w in g[u]:
                if d+w < dist[v][used]:
                    dist[v][used] = d+w
                    heapq.heappush(pq, (d+w, v, used))
                if used < discounts and d+w//2 < dist[v][used+1]:
                    dist[v][used+1] = d+w//2
                    heapq.heappush(pq, (d+w//2, v, used+1))
        return -1

