class Solution:
    def validArrangement(self, pairs):
        from collections import defaultdict, deque
        g = defaultdict(deque)
        indeg = defaultdict(int)
        outdeg = defaultdict(int)
        for u, v in pairs:
            g[u].append(v)
            outdeg[u] += 1
            indeg[v] += 1
        start = pairs[0][0]
        for node in outdeg:
            if outdeg[node] - indeg[node] == 1:
                start = node
                break
        path = []
        stack = [start]
        while stack:
            while g[stack[-1]]:
                stack.append(g[stack[-1]].popleft())
            path.append(stack.pop())
        path.reverse()
        return [[path[i], path[i+1]] for i in range(len(path)-1)]

class Solution:
    def largestEvenSum(self, nums, k):
        nums.sort(reverse=True)
        s = sum(nums[:k])
        if s % 2 == 0: return s
        odd_rest = even_rest = -1
        for i in range(k, len(nums)):
            if nums[i] % 2 == 1 and odd_rest == -1: odd_rest = nums[i]
            if nums[i] % 2 == 0 and even_rest == -1: even_rest = nums[i]
        ans = -1
        for i in range(k-1, -1, -1):
            if nums[i] % 2 == 1 and even_rest != -1:
                ans = max(ans, s - nums[i] + even_rest)
                break
        for i in range(k-1, -1, -1):
            if nums[i] % 2 == 0 and odd_rest != -1:
                ans = max(ans, s - nums[i] + odd_rest)
                break
        return ans

